const listAudit = `-- name: ListAudit :many
SELECT seq, at, user_id, company_id, action, object_type, object_id, before, after, ip, prev_hash, hash FROM platform.audit_log
WHERE company_id = $1 OR company_id IS NULL
ORDER BY seq DESC
LIMIT $2
`

type ListAuditParams struct {
	CompanyID *uuid.UUID
	RowLimit  int32
}

func (q *Queries) ListAudit(ctx context.Context, arg ListAuditParams) ([]PlatformAuditLog, error) {
	rows, err := q.db.Query(ctx, listAudit, arg.CompanyID, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PlatformAuditLog
	for rows.Next() {
		var i PlatformAuditLog
		if err := rows.Scan(
			&i.Seq,
			&i.At,
			&i.UserID,
			&i.CompanyID,
			&i.Action,
			&i.ObjectType,
			&i.ObjectID,
			&i.Before,
			&i.After,
			&i.Ip,
			&i.PrevHash,
			&i.Hash,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

